#include "isr_handlers.h"

/* BENCH ONLY — bootstrap/Vgs test without a debugger. 0 = off (normal FOC duty).
 * Non-zero = TIM1 CH3 (W phase) compare value forced every ISR tick (ARR = 2499,
 * so 2500 = 100% on). Remove before committing. */
#ifndef BENCH_FORCE_PWM_C
#define BENCH_FORCE_PWM_C 0
#endif

/* TIM handles defined in main.c (generated by CubeIDE) */
extern TIM_HandleTypeDef htim1;
extern TIM_HandleTypeDef htim2;

/* -----------------------------------------------------------------------
 * read_phase_currents
 * Reconstruct all three phase currents from the two shunt-sensed phases
 * (U, V); the third follows from KCL (ia + ib + ic = 0). Index map matches
 * the FOC model ports: [2] = U, [1] = V, [0] = derived.
 * ----------------------------------------------------------------------- */
static inline void read_phase_currents(float phase_current[3])
{
  phase_current[2] = (float)(injectedVal[PHASE_U] - currSensOff[PHASE_U]) * ADC_TO_CURR;
  phase_current[1] = (float)(injectedVal[PHASE_V] - currSensOff[PHASE_V]) * ADC_TO_CURR;
  phase_current[0] = 0.0f - phase_current[1] - phase_current[2];

  float the_max = fmaxf(fabsf(phase_current[0]), fmaxf(fabsf(phase_current[1]), fabsf(phase_current[2])));

  d.Max_ph_current = (d.Max_ph_current <= the_max) ? the_max : d.Max_ph_current;
  
}

/* -----------------------------------------------------------------------
 * apply_SVM_voltages
 * Clamp each SVM voltage to ±Vmax_SVM then write the normalised duty
 * cycle to the three TIM1 PWM channels.  Called at the end of every
 * active ISR state so the logic only lives in one place.
 * ----------------------------------------------------------------------- */
void apply_SVM_voltages(void)
{
  d.Va_SVM = fmaxf(-d.Vmax_SVM, fminf(d.Vmax_SVM, d.Va_SVM));
  d.Vb_SVM = fmaxf(-d.Vmax_SVM, fminf(d.Vmax_SVM, d.Vb_SVM));
  d.Vc_SVM = fmaxf(-d.Vmax_SVM, fminf(d.Vmax_SVM, d.Vc_SVM));
  d.pwm_a = (uint16_t)((d.Va_SVM / d.Vmax_SVM) * TIM1_ARR_HALF + TIM1_ARR_HALF);
  d.pwm_b = (uint16_t)((d.Vb_SVM / d.Vmax_SVM) * TIM1_ARR_HALF + TIM1_ARR_HALF);
  d.pwm_c = (uint16_t)((d.Vc_SVM / d.Vmax_SVM) * TIM1_ARR_HALF + TIM1_ARR_HALF);
  #if BENCH_FORCE_PWM_C
  d.pwm_a = 0; //actuaal W phase
  d.pwm_b = d.pwm_c = 0;   /* BENCH ONLY: pins W-phase (CH3) compare, bypasses FOC */
  #endif
  __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, d.pwm_a);
  __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_2, d.pwm_b);
  __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_3, d.pwm_c);
}

/* -----------------------------------------------------------------------
 * isr_curr_sens_calib
 * Accumulates injected ADC readings over NO_OF_SAMPLES ticks to compute
 * per-phase current sensor zero offsets, then transitions to ANGLE_CALIB
 * or FOC_START depending on whether angle auto-tune is required.
 * ----------------------------------------------------------------------- */
void isr_curr_sens_calib(void)
{
  static uint32_t iw_offset = 0;   /* W offset, CAN display only */
  ia_offset += injectedVal[PHASE_U];
  ib_offset += injectedVal[PHASE_V];
  iw_offset += injectedVal[PHASE_W];
  counter++;

  if (counter >= NO_OF_SAMPLES)
  {
    ia_offset = ia_offset / NO_OF_SAMPLES;
    ib_offset = ib_offset / NO_OF_SAMPLES;
    iw_offset = iw_offset / NO_OF_SAMPLES;

    currSensOff[PHASE_U] = ia_offset;
    currSensOff[PHASE_V] = ib_offset;
    currSensOff[PHASE_W] = iw_offset;
    iw_offset = 0;

    ia_offset = 0;
    ib_offset = 0;
    counter   = 0;

    /* Switch TIM1 to the run-phase PWM rate and restore encoder count from PWM duty */
    __HAL_TIM_SET_PRESCALER(&htim1, TIM1_PSC_RUN);
    __HAL_TIM_SET_AUTORELOAD(&htim1, TIM1_ARR);
    __HAL_TIM_SET_COUNTER(&htim2, d.Count_From_Duty);

    d.elec_angle = 0.0f;

    /* Boot fault gate. With ENABLE_FAULTS the initial check decides whether
     * we may leave calibration at all; with DISABLE_FAULTS (bench builds)
     * the check is skipped and the drive always proceeds. vehicle_config.h
     * enforces that exactly one of the two flags is set, so the fall-through
     * below is reached on precisely one path. */
    #if ENABLE_FAULTS
    d.init_check = Initial_Fault_Check();

    if (d.init_check != HAL_OK)
    {
      HAL_GPIO_WritePin(DRIVE_INHIBIT_GPIO_Port, DRIVE_INHIBIT_Pin, GPIO_PIN_SET);
      cS = CONT_ERROR;
      disable_drive();
      return;
    }
    #endif

    /* Fault-free: release the drive inhibit, then run angle calibration if
     * the stored offsets are absent (or forced), otherwise go straight to FOC. */
    HAL_GPIO_WritePin(DRIVE_INHIBIT_GPIO_Port, DRIVE_INHIBIT_Pin, GPIO_PIN_RESET);
    if ((d.start_alignment == 1 && d.end_alignment == 0) || FORCE_ANGLETUNE) {
      FOC_Loop_U.Speed_1_Torque_0 = FOC_MODE_SPEED;
      cS = FOC_START;
    } else {
      FOC_Loop_U.Speed_1_Torque_0 = OPERATION_MODE;
      cS = FOC_START;
    }
  }
}

/* -----------------------------------------------------------------------
 * isr_angle_calib
 * Runs the AngleAutotuning routine at AUTOTUNE_UPDATE_MS cadence.
 * Drives either the open-loop or closed-loop FOC model depending on the
 * autotune algorithm's current loop status, then commits the result to
 * ANGLE_OFFSET_STORE once calibration is complete.
 * ----------------------------------------------------------------------- */
void isr_angle_calib(void)
{
  static uint8_t autotune_tick_ms = 0;
  autotune_tick_ms++;

  TagAutotuneInput.AutotuneFlag = TagAutotuneOutput.AutotuneCompleteflag
                                    ? NORMAL_RUN : ANGLE_AUTOTUNE;

  if (autotune_tick_ms >= AUTOTUNE_UPDATE_MS)
  {
    autotune_tick_ms = 0;
    TagAutotuneInput.f_Pwmangle = d.abs_Angle_pwm;
    TagAutotuneInput.f_MotorRpm = d.RPM;
    TagAutotuneInput.f_Vq = FOC_Loop_Y.Vq;
    TagAutotuneInput.f_Vd = FOC_Loop_Y.Vd;

    AngleAutotuningRoutine(&TagAutotuneInput, &TagAutotuneOutput, &TagAutotuneDebug);

    d.offset_angle_mech_cw  = TagAutotuneOutput.f_Offset_CW;
    d.offset_angle_mech_ccw = TagAutotuneOutput.f_Offset_CCW;
  }

  if (TagAutotuneOutput.MotorloopStatus == Open_Loop)
  {
    d.Open_FOC = 1;
    d.Closed_FOC = 0;

    read_phase_currents(Open_FOC0_U.Phase_current);

    Open_FOC0_U.Id_ref      = TagAutotuneOutput.f_Idref;
    Open_FOC0_U.Iq_ref      = TagAutotuneOutput.f_Iqref;
    Open_FOC0_U.Theta_e_ref = TagAutotuneOutput.f_Electricalangle;

    Open_FOC0_step();

    d.Va_SVM = Open_FOC0_Y.Va;
    d.Vb_SVM = Open_FOC0_Y.Vb;
    d.Vc_SVM = Open_FOC0_Y.Vc;
  }
  else if (TagAutotuneOutput.MotorloopStatus == Closed_Loop)
  {
    d.Open_FOC = 0;
    d.Closed_FOC = 1;

    read_phase_currents(FOC_Loop_U.PhaseCurrent);

    FOC_Loop_U.Throttle_input.Throttle_Inst_Voltage = THR_MIN_VAL;
    FOC_Loop_U.Ref_Speed_mech_rpm = TagAutotuneOutput.f_MotorRpmRef;

    if (TagAutotuneOutput.CalibrationDirection == Motor_Forward) {
      FOC_Loop_U.Drive_State = Forward;
      d.ATA_Offset = TagAutotuneOutput.f_Offset_CW;
    } else if (TagAutotuneOutput.CalibrationDirection == Motor_Reverse) {
      FOC_Loop_U.Drive_State = Reverse;
      d.ATA_Offset = TagAutotuneOutput.f_Offset_CCW;
    } else if (TagAutotuneOutput.CalibrationDirection == Motor_Neutral) {
      FOC_Loop_U.Drive_State = Neutral;
    } else {
      FOC_Loop_U.Drive_State = Throttle_Error;
    }

    d.encoder_count = __HAL_TIM_GET_COUNTER(&htim2);
    d.mech_angle    = ((float)d.encoder_count * COUNTS_TO_RADS) - d.ATA_Offset;
    d.mech_angle    = fmodf(d.mech_angle, TWO_PI);
    if (d.mech_angle < 0.0f) d.mech_angle += TWO_PI;

    d.elec_angle = fmodf(d.mech_angle * POLEPAIRS, TWO_PI);
    FOC_Loop_U.angle = d.elec_angle;

    rt_OneStep();

    d.Va_SVM = FOC_Loop_Y.Va;
    d.Vb_SVM = FOC_Loop_Y.Vb;
    d.Vc_SVM = FOC_Loop_Y.Vc;
  }

  if (TagAutotuneOutput.AutotuneCompleteflag == true)
  {
    d.start_alignment       = 0;
    d.end_alignment         = 1;
    d.offset_angle_mech_cw  = TagAutotuneOutput.f_Offset_CW;
    d.offset_angle_mech_ccw = TagAutotuneOutput.f_Offset_CCW;
    cS = ANGLE_OFFSET_STORE;
  }

  apply_SVM_voltages();
}

/* -----------------------------------------------------------------------
 * isr_foc_start
 * Main closed-loop FOC ISR path.  Reads phase currents and encoder angle,
 * runs the rt_OneStep() model, then updates PWM outputs.
 * DWT cycle count (when EST_CYC_CNT=1) gives real-time budget visibility.
 * ----------------------------------------------------------------------- */
void isr_foc_start(void)
{
  #if EST_CYC_CNT
  uint32_t start = DWT->CYCCNT;
  #endif

  read_phase_currents(FOC_Loop_U.PhaseCurrent);

  /* Mechanical → electrical angle. The CW/CCW commutation offsets are keyed
   * on Throttle_State (the model/electrical frame), so they track the actual
   * rotation direction and need no handling for the MOTOR_DIRECTION flip.
   * Throttle_Error resolves to 0.0f, matching the original fall-through that
   * subtracted nothing. */
  d.encoder_count = __HAL_TIM_GET_COUNTER(&htim2);

  float offset = 0.0f;
  if      (FOC_Loop_Y.Throttle_State == (ThrottleState)FORWARD) {
    offset = d.offset_angle_mech_cw;
  }
  else if (FOC_Loop_Y.Throttle_State == (ThrottleState)REVERSE) {
    offset = d.offset_angle_mech_ccw;
  }
  else if (FOC_Loop_Y.Throttle_State == (ThrottleState)NEUTRAL) {
    offset = d.offset_angle_mech_avg;
  }

#if FOC_ANGLE_ADVANCE
  /* Dynamic commutation advance (see vehicle_config.h). The calibrated offset
   * is optimal at standstill but over-lags at speed: the ISR->PWM latency
   * advances the true rotor past the applied vector by ~w_e*dt, and high
   * current shifts the angle further. Reducing the offset by up to ADV_MECH_MAX
   * recovers the 26-45 km/h band, the accel pull-back and top speed. It is
   * applied ONLY while MOTORING and only at speed: a fixed advance jerks the
   * vehicle on hard decel, so it is gated by an RPM ramp (zero at launch) and
   * the driver drive-torque (zero on release/braking).
   *
   * The advance MUST carry the sign of the rotor direction. The correction
   * predicts where the rotor will be when the PWM actually lands,
   *     theta_used = theta_sampled + w_m*dt,
   * and w_m is signed; since mech_angle = count*K - offset, adding to the
   * angle means SUBTRACTING from the offset, so the term to subtract is
   * signed too. Advancing unconditionally (i.e. off |RPM| alone) is right
   * only while the rotor turns in the +count direction — the other way it
   * moves the angle the WRONG way and roughly DOUBLES the latency error
   * instead of cancelling it.
   *
   * d.RPM is the differentiated mech_angle, so its sign IS the rotor
   * direction relative to the encoder. Which gear that corresponds to
   * depends on the model's Throttle_State, and MOTOR_DIRECTION is what maps
   * the driver's lever onto it:
   *   DIR_NORMAL: driver Forward -> Throttle_State Forward -> d.RPM > 0
   *   DIR_FLIP  : driver Forward -> Throttle_State Reverse -> d.RPM < 0
   * so on a DIR_FLIP build an unsigned advance would be wrong across the
   * ENTIRE primary driving range, not just in reverse. Keying off measured
   * d.RPM instead of a build flag keeps this correct for both gears and
   * either MOTOR_DIRECTION, with nothing to keep in sync when the gearbox
   * orientation changes. Sign is well defined here: the advance is zero
   * below ADV_RPM_LO, so there is no zero-crossing chatter. */
  {
    float rpm_frac = (fabsf(d.RPM) - ADV_RPM_LO) / (ADV_RPM_HI - ADV_RPM_LO);
    rpm_frac = fmaxf(0.0f, fminf(1.0f, rpm_frac));
    float trq_gate = (d.torque_final - ADV_TRQ_LO) / (ADV_TRQ_HI - ADV_TRQ_LO);
    trq_gate = fmaxf(0.0f, fminf(1.0f, trq_gate));
    offset -= copysignf(ADV_MECH_MAX * rpm_frac * trq_gate, d.RPM);
  }
#endif

  /* Kept as two steps, matching the original multiply-then-subtract: folding
   * them into one expression would let the compiler contract it to an FMA and
   * round once instead of twice. Immaterial in magnitude, but there is no
   * reason for a refactor to move the result at all. */
  d.mech_angle  = (float)d.encoder_count * COUNTS_TO_RADS;
  d.mech_angle -= offset;
  d.mech_angle  = fmodf(d.mech_angle, TWO_PI);
  if (d.mech_angle < 0.0f) d.mech_angle += TWO_PI;
  d.elec_angle = fmodf(d.mech_angle * POLEPAIRS, TWO_PI);

  FOC_Loop_U.angle = d.elec_angle;

  #if HILL_HOLD_ENABLE
  /* Hill hold may raise RefTrq as a torque floor against rollback. Must run
   * right before rt_OneStep so it wins over the background-loop throttle
   * write within the same tick.
   *
   * MUST be passed d.torque_final — the superloop's driver-demand variable,
   * which this module never writes. Passing FOC_Loop_U.RefTrq feeds the
   * module its own output and makes this a read-modify-write on shared
   * state: between two superloop writes the ISR reads the floored result
   * back as "driver demand", so max() ratchets the command up to the highest
   * torque seen in the window, and the takeover test (demand > hold torque)
   * ends up comparing the hold against itself.
   *
   * Torque mode only: in speed mode the superloop stops maintaining
   * d.torque_final, so the result is not written to RefTrq. The module is
   * still stepped so it observes the mode change and resets, leaving no
   * stale hold torque to apply on the way back. */
  float hh_reftrq = HillHold_Apply(d.torque_final);
  if (FOC_Loop_U.Speed_1_Torque_0 == FOC_MODE_TORQUE) {
    FOC_Loop_U.RefTrq = hh_reftrq;
  }
  #endif

  rt_OneStep();

  /* Voltage-headroom diagnostic -> CAN 0x715 byte[1]. Sampled here, BEFORE
   * apply_SVM_voltages(), because this is the last point where the voltage the
   * regulator believes it applied is still intact; the per-phase clamp below is
   * exactly what discards it. Unconditional (no #if) so a baseline run and an
   * experimental run are directly comparable. See data_t.mod_index_peak. */
  if (d.Vmax_SVM > 1.0f) {
#if FOC_VDQ_CIRCLE_LIMIT
    float v_mag = d.vdq_demand / d.Vmax_SVM;  /* pre-limit pair, see FOC_Loop.c */
#else
    float v_mag = sqrtf((FOC_Loop_Y.Vd * FOC_Loop_Y.Vd) +
                        (FOC_Loop_Y.Vq * FOC_Loop_Y.Vq)) / d.Vmax_SVM;
#endif
    if (v_mag > d.mod_index_peak) d.mod_index_peak = v_mag;
  }

  #if FOC_BENCH_FAST_TLM
  Fast_Tlm_Accumulate();
  #endif

  d.Va_SVM = FOC_Loop_Y.Va;
  d.Vb_SVM = FOC_Loop_Y.Vb;
  d.Vc_SVM = FOC_Loop_Y.Vc;

  apply_SVM_voltages();

  #if EST_CYC_CNT
  d.cycles = DWT->CYCCNT - start;
  #endif
}

void isr_open_foc(void){
  #if EST_CYC_CNT
  uint32_t start = DWT->CYCCNT;
  #endif

    d.Open_FOC = 1;
    d.Closed_FOC = 0;

    read_phase_currents(Open_FOC0_U.Phase_current);

    Open_FOC0_U.Id_ref      = TagAutotuneOutput.f_Idref;
    Open_FOC0_U.Iq_ref      = TagAutotuneOutput.f_Iqref;
    Open_FOC0_U.Theta_e_ref = TagAutotuneOutput.f_Electricalangle;

    Open_FOC0_step();

    d.Va_SVM = Open_FOC0_Y.Va;
    d.Vb_SVM = Open_FOC0_Y.Vb;
    d.Vc_SVM = Open_FOC0_Y.Vc;

    apply_SVM_voltages();

  #if EST_CYC_CNT
  d.cycles = DWT->CYCCNT - start;
  #endif
}
